// 查重：日期＋標題一樣就算同一筆，不重寫（重送也不會多一筆）
const rows = $input.all().map(i => i.json).filter(r => r['日期']);
const keys = new Set(rows.map(r => r['日期'] + '|' + r['標題']));
const add = $('行程助理').first().json.output.events
  .map(e => ({ '日期': e.date, '開始': e.start, '結束': e.end, '標題': e.title, '地點': e.place }))
  .filter(r => !keys.has(r['日期'] + '|' + r['標題']));
if (add.length === 0) return [];   // 全部都已經有了：0 筆，後面不寫
return [...rows, ...add].map(r => ({ json: r }));
